# eski değil, bataryanın yas_araligi sporcunun yaşını kapsıyor (aralık None ise bu şart aranmaz).
YON_YARIM_ORAN = 0.5
YON_YARIM_GUN = 42
YON_SUSTUR_ANAHTAR = "yarim_susturulan"   # ayarlar.json: [[sporcu, batarya], …] — "Bu bataryayı bitirmeyeceğim"


def ayar_oku():
    """Yerel tercihler (ayarlar.json). Dosya yoksa ya da bozuksa boş sözlük — ekran yine açılır."""
    try:
        with open(AYAR_DOSYA, encoding="utf-8") as f:
            veri = _json.load(f)
        return veri if isinstance(veri, dict) else {}
    except (OSError, ValueError):
        return {}


def ayar_yaz(anahtar, deger):
    veri = ayar_oku()
    veri[anahtar] = deger
    try:
        with open(AYAR_DOSYA, "w", encoding="utf-8") as f:
            _json.dump(veri, f, ensure_ascii=False, indent=1)
    except OSError:
        pass


def katalog_testleri(katalog=None):
    """Katalogdaki her test: {"ad", "yol": (kategori, alt, branş|None), "kategori"} — Test ara bunu tarar."""
    katalog = TEST_KATALOGU if katalog is None else katalog
    liste = []
    for kat, altlar in katalog.items():
        for alt, icerik in altlar.items():
            if alt.startswith("_") or not isinstance(icerik, dict):
                continue
            if "protokol" in icerik:
                liste.append({"ad": alt, "yol": (kat, None, None), "kategori": kat})
                continue
            for ad, v in icerik.items():
                if ad.startswith("_") or not isinstance(v, dict):
                    continue
                if "protokol" in v:
                    liste.append({"ad": ad, "yol": (kat, alt, None), "kategori": kat})
                else:
                    for t, tv in v.items():
                        if not t.startswith("_") and isinstance(tv, dict) and "protokol" in tv:
                            liste.append({"ad": t, "yol": (kat, alt, ad), "kategori": kat})
    return liste


def katalog_bataryalari(katalog=None):
    """{(kategori, batarya): [test, …]} — yalnız YON_BATARYA_KATEGORILERI altındaki gerçek bataryalar."""
    katalog = TEST_KATALOGU if katalog is None else katalog
    out = {}
    for kat in YON_BATARYA_KATEGORILERI:
        for bat, icerik in katalog.get(kat, {}).items():
            if bat.startswith("_") or bat in YON_BATARYA_DISI or not isinstance(icerik, dict):
                continue
            testler = [t for t, v in icerik.items() if not t.startswith("_") and isinstance(v, dict) and "protokol" in v]
            if testler:
                out[(kat, bat)] = testler
    return out


def ilgi_eki(ad):
    """Türkçe ilgi eki ('Deniz Aydın' → 'Deniz Aydın’ın', 'Ali Bir' → 'Ali Bir’in', 'Ece' → 'Ece’nin')."""
    ad = str(ad).strip()
    unluler = {"a": "ı", "ı": "ı", "A": "ı", "I": "ı", "e": "i", "i": "i", "E": "i", "İ": "i",
               "o": "u", "u": "u", "O": "u", "U": "u", "ö": "ü", "ü": "ü", "Ö": "ü", "Ü": "ü"}
    son = next((unluler[c] for c in reversed(ad) if c in unluler), "i")
    return f"{ad}’{'n' if ad[-1:] in unluler else ''}{son}n"


def batarya_kisa(bat):
    return YON_BATARYA_KISA.get(bat, bat)


def test_kisa(test, bat):
    """Cümlede test adı: bataryanın kısa adı parantezde/tireyle tekrar ediyorsa atılır ('20m Sürat (TSYT)' → '20m Sürat')."""
    k = re.escape(batarya_kisa(bat))
    return re.sub(rf"\s*(\({k}\)|— {k})$", "", test).strip() or test


def _tablo_guvenli(df, kolonlar):
    """Dosya yoksa (None), boşsa ya da sütun eksikse: hata yerine boş/eksiksiz tablo."""
    if df is None or not isinstance(df, pd.DataFrame):
        df = pd.DataFrame()
    df = df.copy()
    for k in kolonlar:
        if k not in df.columns:
            df[k] = ""
    return df


def tablo_oku(yol):
    """xlsx'i okur; dosya yoksa ya da okunamıyorsa None (yönlendirme ekranı hata vermeden açılsın)."""
    if not os.path.exists(yol):
        return None
    try:
        return pd.read_excel(yol)
    except Exception:
        return None


def batarya_yas_araligi(kategori, batarya, katalog=None):
    """Bataryanın _kunye'sindeki yas_araligi (min, max) ya da None."""
    katalog = TEST_KATALOGU if katalog is None else katalog
    k = (katalog.get(kategori, {}).get(batarya, {}) or {}).get("_kunye") or {}
    ya = k.get("yas_araligi") if isinstance(k, dict) else None
    return tuple(ya) if ya else None


def yarim_susturulanlar():
    """Susturulan (sporcu, batarya) çiftleri — ayarlar.json'dan; dosya yoksa/bozuksa boş."""
    v = ayar_oku().get(YON_SUSTUR_ANAHTAR, [])
    return {(str(x[0]), str(x[1])) for x in v if isinstance(x, (list, tuple)) and len(x) == 2} if isinstance(v, list) else set()


def yarim_sustur(sporcu, batarya):
    """"Bu bataryayı bitirmeyeceğim": o sporcu + batarya bir daha yarım sayılmaz (başka sporcuyu etkilemez)."""
    s = yarim_susturulanlar() | {(str(sporcu), str(batarya))}
    ayar_yaz(YON_SUSTUR_ANAHTAR, sorted([list(x) for x in s]))


def yonlendirme_durumu(df_sporcu, df_test, katalog=None, bugun=None, susturulan=()):
    """
    Veride ne var: sporcu sayısı, sonuç sayısı, yarım kalan ve tamamlanan bataryalar (sporcu adıyla).
    Bütün testleri yapılmış batarya tamamdır. Eksik testi olan batarya yalnız ÜÇ şart birden sağlanırsa yarım
    sayılır (Paket 32 — tek test bataryayı "başlatmaz"): testlerin en az yarısı yapılmış; bataryadaki son ölçüm
    YON_YARIM_GUN günden eski değil; bataryanın yas_araligi sporcunun yaşını kapsıyor (None ise aranmaz; yaş ya da
    tarih bilinmiyorsa şart sağlanmış sayılmaz). susturulan: {(sporcu, batarya)} — o çift yarım sayılmaz.
    Tahmin yok: yalnız kayıtlı sonuçlar sayılır.
    """
    bugun = tarih_coz(bugun) or date.today()
    susturulan = {tuple(x) for x in susturulan}
    sp = _tablo_guvenli(df_sporcu, ["Ad", "Soyad", "Yaş"])
    ts = _tablo_guvenli(df_test, ["Sporcu", "Test", "Tarih"])
    adlar, yaslar = [], {}
    for _, r in sp.iterrows():
        ad = f"{'' if pd.isna(r['Ad']) else r['Ad']} {'' if pd.isna(r['Soyad']) else r['Soyad']}".strip()
        if ad and ad not in adlar:
            adlar.append(ad)
            y = tam_yas(r.get(DOGUM_KOLON), bugun)            # doğum tarihi varsa bugünkü yaş, yoksa profil yaşı
            if y is None:
                try:
                    y = None if pd.isna(r["Yaş"]) or str(r["Yaş"]).strip() == "" else int(float(r["Yaş"]))
                except (TypeError, ValueError):
                    y = None
            yaslar[ad] = y
    ts = ts[ts["Sporcu"].astype(str).isin(adlar)] if adlar else ts.iloc[0:0]
    yapilan = {a: set(ts.loc[ts["Sporcu"].astype(str) == a, "Test"].astype(str)) for a in adlar}
    yarim, tamam = [], []
    for (kat, bat), testler in katalog_bataryalari(katalog).items():
        ya = batarya_yas_araligi(kat, bat, katalog)
        for a in adlar:
            if not yapilan[a] & set(testler):
                continue
            eksik = [t for t in testler if t not in yapilan[a]]
            kayit = {"sporcu": a, "kategori": kat, "batarya": bat, "eksik": eksik, "toplam": len(testler)}
            if not eksik:
                tamam.append(kayit)
                continue
            satir = ts[(ts["Sporcu"].astype(str) == a) & ts["Test"].astype(str).isin(testler)]
            tarihler = [d_ for d_ in (tarih_coz(x) for x in satir["Tarih"]) if d_ is not None]
            son = max(tarihler) if tarihler else None
            yas = yaslar.get(a)
            if ((len(testler) - len(eksik)) >= YON_YARIM_ORAN * len(testler)            # a) en az yarısı
                    and son is not None and (bugun - son).days <= YON_YARIM_GUN          # b) son ölçüm ≤ 6 hafta
                    and (ya is None or (yas is not None and ya[0] <= yas <= ya[1]))     # c) yaş aralıkta
                    and (a, bat) not in susturulan):
                yarim.append(dict(kayit, son_olcum=son))
    if not adlar:
        durum = "sporcu_yok"
    elif ts.empty:
        durum = "sonuc_yok"
    else:
        durum = "sonuc_var"
    return {"durum": durum, "sporcular": adlar, "sonuc_sayisi": int(len(ts)),
            "sonucsuz": [a for a in adlar if not yapilan[a]], "yarim": yarim, "tamam": tamam}


def yarim_cumlesi(k):
    """'Deniz Aydın’ın TSYT bataryasında 2 test eksik: 20m Sürat, Mekik Koşusu'"""
    return (f"{ilgi_eki(k['sporcu'])} {batarya_kisa(k['batarya'])} bataryasında {len(k['eksik'])} test eksik: "
            + ", ".join(test_kisa(t, k["batarya"]) for t in k["eksik"]))


def tamam_cumlesi(k):
    return f"{ilgi_eki(k['sporcu'])} {batarya_kisa(k['batarya'])} bataryası tamam ({k['toplam']} test)."


# ════════════════════════════════════════════════════════════
# PAKET 27 — KENDİ TEST SETİNİ KURABİLME
# Kategori test seçimini kilitlemez: kategori ağacı gezinmek içindir; branş hangi testin ÖNERİLECEĞİNİ belirler,
# hangisinin YAPILABİLECEĞİNİ değil. Çalışma (ayarlar.json): ad, sıralı testler, gruplar, ölçüm zamanları, sporcu →
# grup ataması. Sporcu ve test dosyalarının yapısı değişmez.
# ════════════════════════════════════════════════════════════

# Aynı test iki yerde kayıtlı: takma ad → asıl ad. Kayıt asıl adla yazılır; eski kayıtlar okunurken asıl ada
# çevrilir (dosya yeniden yazılmaz — veri kaybolmaz, aynı sporcunun verisi ikiye bölünmez).
TEST_TAKMA_AD = {
    "Nordic Hamstring Kuvvet Testi (NHT)": "Nordic Hamstring Kuvvet Testi — Genel (NHT)",
    # Paket 30: eski ad (katalogda artık yok; eski kayıtlar okunurken yeni ada çevrilir)
    "Tenis Çeviklik T-Testi": "T-Testi (Çeviklik)",
    # Paket 30: branş raflarındaki gerçek tekrarlar — rafta görünürler, veri genel sürümde toplanır
    **{f"Yo-Yo IR1 ({b})": "Yo-Yo IR1 (Genel)" for b in (
        "Güreş", "Judo", "Tenis", "Muay Thai", "BJJ", "Badminton", "Masa Tenisi", "Squash", "Karate", "Taekwondo",
        "Boks", "Futbol", "Basketbol", "Voleybol", "Hentbol")},
    **{f"Wingate ({b})": "Wingate 30sn Bisiklet Testi" for b in ("Muay Thai", "MMA", "Kickboks")},
    "Yo-Yo IR2 (Futbol)": "Yo-Yo IR2 (Genel)",          # Paket 31: aynı gerekçe (değişkenler aynı)
}


def kanonik_test(ad):
    """Takma adı asıl test adına çevirir; başka her ad olduğu gibi döner."""
    return TEST_TAKMA_AD.get(ad, ad)


def test_tablosu_duzelt(df):
    """Okunan sonuç tablosunda takma adlı kayıtları asıl ada çevirir (yalnız bellekte; dosya değişmez)."""
    if isinstance(df, pd.DataFrame) and "Test" in df.columns:
        df = df.copy()
        df["Test"] = df["Test"].map(lambda t: kanonik_test(t) if isinstance(t, str) else t)
    return df


def test_raflari(ad, katalog=None):
    """Testin (ve takma adlarının) katalogdaki bütün yerleri [(kategori, alt, branş)] — "ayrıca şu raflarda"."""
    asil = kanonik_test(ad)
    return [t["yol"] for t in katalog_testleri(katalog) if kanonik_test(t["ad"]) == asil]


def test_izi_parcalari(ad, yol=None, katalog=None):
    """
    (seçili rafın yolu metni, ["ayrıca" rafları]) — yol (kategori, alt|None, branş|None) verilmezse testin kendi
    adıyla durduğu raf, o da yoksa ilk raf. "ayrıca" rafları kısa adla (branş, yoksa alt başlık).
    """
    raflar = test_raflari(ad, katalog)
    yol = tuple(yol) if yol else None
    if yol not in raflar:
        kendi = [t["yol"] for t in katalog_testleri(katalog) if t["ad"] == ad]
        yol = kendi[0] if kendi else (raflar[0] if raflar else None)
    if yol is None:
        return "", []
    diger = list(dict.fromkeys(r[2] or r[1] or r[0] for r in raflar if r != yol))
    return " › ".join(p for p in yol if p), diger


def test_izi(ad, yol=None, katalog=None):
    """Örnek: Branşa Özgü Testler › Bireysel Sporlar › Güreş › Special Wrestling Fitness Test (SWFT) · anaerobik."""
    yol_metni, diger = test_izi_parcalari(ad, yol, katalog)
    iz = " › ".join(p for p in (yol_metni, test_etiketli(ad)) if p)
    if diger:
        ek = ", ".join(diger[:ONERI_IZ_SINIRI]) + (f" ve {len(diger) - ONERI_IZ_SINIRI} rafta daha"
                                                   if len(diger) > ONERI_IZ_SINIRI else "")
        iz += f" — ayrıca: {ek}"
    return iz


def test_yolu(ad, katalog=None):
    """Testin katalogdaki ilk yeri → (kategori, batarya, branş|None); kayıttaki Kategori/Batarya/Branş için."""
    for t in katalog_testleri(katalog):
        if t["ad"] == ad:
            kat, alt, brans = t["yol"]
            return kat, alt if alt is not None else kat, brans
    return None


def test_bilgisi(ad, katalog=None):
    """Testin katalog kaydı (protokol, değişkenler…); takma ad asıl teste çözülür."""
    yol = test_yolu(kanonik_test(ad), katalog)
    if not yol:
        return None
    katalog = TEST_KATALOGU if katalog is None else katalog
    kat, bat, brans = yol
    d = katalog[kat] if bat == kat else katalog[kat][bat]
    d = d[brans] if brans else d
    return d[kanonik_test(ad)]


# ── C) Ölçülen nitelik ve sıra uyarısı (ExRx test bataryası ilkeleri) ──
# Tek taksonomi (Paket 30): her test bir NİTELİĞE eşlenir (gösterim: "10m Sprint (sürat)"); sıra denetimi
# niteliğin bağlı olduğu ExRx BİLEŞENİNİ kullanır. Sıra: antropometri → esneklik → sürat ve çeviklik → güç →
# kuvvet → kas dayanıklılığı → kardiyo; en yorucu sona. Eşleme test adındaki ölçülen niteliğe göre kuraldır.
